  1: {
    'UPGRADERS_QUANTITY': 5
  },
  2: {},
  3: {},
  4: {
    'DEDICATED_MINERS': true,
    'PURE_CARRY_FILLERS': true
  },
  5: {},
  6: {
    'EXTRACT_MINERALS': true
  },
  7: {},
  8: {
    'UPGRADERS_QUANTITY': 1
  }
}

