  };
  render() {
    const { children, style, className, disabled } = this.props;
    return (
      <Dropzone
        disabled={disabled}
        onClick={(evt) => evt.preventDefault()}
        multiple={false}
        accept={[".gb", ".gbk", ".fasta", ".fa", ".gp", ".txt", ".dna"]}
        activeClassName="isActive"
